<?php
require_once 'config.php'; require_login();
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $rid=filter_input(INPUT_POST,'registration_id',FILTER_VALIDATE_INT); if ($rid) { $stmt=$pdo->prepare('DELETE FROM registrations WHERE registration_id=? AND user_id=?'); $stmt->execute([$rid,$_SESSION['user_id']]); set_flash($stmt->rowCount() ? 'Registration cancelled.' : 'Registration was not found.','success'); } redirect('my_events.php'); }
$pageTitle='My Events'; $stmt=$pdo->prepare('SELECT r.registration_id,r.registered_at,e.event_id,e.title,e.description,e.event_date,e.venue FROM registrations r JOIN events e ON r.event_id=e.event_id WHERE r.user_id=? ORDER BY e.event_date ASC'); $stmt->execute([$_SESSION['user_id']]); $registrations=$stmt->fetchAll(); require 'header.php';
?>
<section class="page-intro"><span class="eyebrow">YOUR CAMPUS PLAN</span><h1>My Events</h1><p>Keep track of the campus events you have registered for.</p></section>
<?php if (!$registrations): ?><div class="empty-state"><h3>You haven't registered for any events yet</h3><p>Browse the event list and find something to join.</p><a class="btn btn-primary" href="events.php">Browse events</a></div><?php else: ?><div class="my-events-list"><?php foreach ($registrations as $reg): ?><article class="my-event"><div class="event-date"><span><?= e(date('M',strtotime($reg['event_date']))) ?></span><strong><?= e(date('d',strtotime($reg['event_date']))) ?></strong></div><div class="my-event-info"><h3><a href="event.php?id=<?= (int)$reg['event_id'] ?>"><?= e($reg['title']) ?></a></h3><p>⌖ <?= e($reg['venue']) ?> · <?= e(date('M d, Y · g:i A',strtotime($reg['event_date']))) ?></p><span class="muted small">Registered <?= e(date('M d, Y',strtotime($reg['registered_at']))) ?></span></div><form method="post" onsubmit="return confirm('Cancel this event registration?');"><input type="hidden" name="csrf_token" value="<?= e($_SESSION['csrf_token']) ?>"><input type="hidden" name="registration_id" value="<?= (int)$reg['registration_id'] ?>"><button class="btn btn-outline" type="submit">Cancel</button></form></article><?php endforeach; ?></div><?php endif; ?>
<?php require 'footer.php'; ?>
